let engagement={},commentGame=null,commentsRequest=0;
async function api(url,options={}){const response=await fetch(url,{credentials:'same-origin',...options});let result;try{result=await response.json()}catch{throw Error('The QuickPlay server is unavailable. Open the server preview and try again.')}if(!response.ok)throw Error(result.error||'Something went wrong. Please try again.');return result}
function socialButtons(c){if(c.el.querySelector('.like'))return;const actions=c.el.querySelector('.actions');const like=document.createElement('button');like.className='action like';like.setAttribute('aria-label','Like '+c.g.title);like.innerHTML='<span>♥</span><small>0</small>';like.onclick=async()=>{like.disabled=true;try{engagement[c.g.id]=await api('/api/likes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({gameId:c.g.id,liked:!engagement[c.g.id]?.liked})});updateSocial(c)}catch(e){toast(e.message)}finally{like.disabled=false}};const comments=document.createElement('button');comments.className='action comments';comments.setAttribute('aria-label','Comments on '+c.g.title);comments.innerHTML='<span>☷</span><small>0</small>';comments.onclick=()=>openComments(c.g.id);actions.prepend(comments);actions.prepend(like);updateSocial(c)}
function updateSocial(c){const s=engagement[c.g.id]||{likes:0,comments:0,liked:false};const b=c.el.querySelector('.like');if(!b)return;b.classList.toggle('liked',s.liked);b.setAttribute('aria-pressed',String(s.liked));b.querySelector('small').textContent=s.likes;b.setAttribute('aria-label',`${s.liked?'Unlike':'Like'} ${c.g.title}, ${s.likes} likes`);c.el.querySelector('.comments small').textContent=s.comments}
cards.forEach(socialButtons);
function addUpload(item){if(cards.has(item.id))return;const g={...item,upload:true,uploadKind:item.kind,kind:3,color:'#d5ff5f',tags:item.kind==='html'?'Community demo · Instant play':'Community gameplay · Video',instruction:''};games.push(g);stats[g.id]={starts:0,seconds:0,details:0};const el=makeCard(g);el.querySelector('.demo-label').textContent=item.kind==='html'?'✦ Community demo':'▷ Gameplay video';el.querySelector('.pill').textContent=g.genre.toUpperCase();el.querySelector('.play').textContent=item.kind==='html'?'▶ Play demo':'▶ Watch video';const cover=document.createElement('div');cover.className='upload-cover';const type=document.createElement('span');type.className='overline';type.textContent=item.kind==='html'?'COMMUNITY PLAYABLE':'GAMEPLAY DROP';const title=document.createElement('h3');title.textContent=g.title;const badge=document.createElement('span');badge.className='upload-emblem';badge.textContent=item.kind==='html'?'▶':'▷';cover.append(badge,type,title);el.append(cover);feed.prepend(el);el.classList.toggle('hidden',filter!=='All'&&g.genre!==filter);socialButtons(cards.get(g.id))}
async function refreshFeed(){const data=await api('/api/games');engagement=data.engagement;data.uploads.slice().reverse().forEach(addUpload);cards.forEach(updateSocial);updateSaved();document.querySelector('.edition span').textContent=String(games.length).padStart(2,'0')+' GAMES'}
function startUpload(c){const player=document.createElement(c.g.uploadKind==='html'?'iframe':'video');player.className='upload-player';if(c.g.uploadKind==='html'){player.setAttribute('sandbox','allow-scripts');player.title=c.g.title;player.referrerPolicy='no-referrer'}else{player.controls=true;player.playsInline=true;player.autoplay=true;player.addEventListener('error',()=>toast('This video could not be played. Try a supported MP4 or WebM.'))}player.src=c.g.url;c.el.append(player);c.state={};c.el.classList.add('playing');c.el.querySelector('.play').textContent='Close player';stats[c.g.id].starts++;if(player.tagName==='VIDEO')player.play().catch(()=>{})}
function commentStatus(message){$('#comment-status').textContent=message}
async function openComments(id){stop();commentGame=id;const g=games.find(g=>g.id===id);$('#comments-title').textContent=g.title;commentStatus('');$('#comments-dialog').showModal();await loadComments(id)}
async function loadComments(id){const request=++commentsRequest,box=$('#comments-list');box.textContent='Loading comments…';try{const result=await api('/api/comments/'+encodeURIComponent(id));if(request!==commentsRequest||commentGame!==id)return;box.replaceChildren();if(!result.comments.length){const p=document.createElement('p');p.className='empty-comments';p.textContent='Be the first to start the conversation.';box.append(p)}result.comments.forEach(item=>{const row=document.createElement('article');row.className='comment-row';const avatar=document.createElement('span');avatar.className='comment-avatar';avatar.textContent=item.name[0].toUpperCase();const content=document.createElement('div');const name=document.createElement('b');name.textContent=item.name;const date=document.createElement('time');date.textContent=new Date(item.created.replace(' ','T')+'Z').toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});const body=document.createElement('p');body.textContent=item.body;content.append(name,date,body);row.append(avatar,content);box.append(row)})}catch(e){if(request===commentsRequest){box.textContent='Comments could not load.';commentStatus(e.message)}}}
$('#close-comments').onclick=()=>$('#comments-dialog').close();$('#comments-dialog').onclick=e=>{if(e.target===$('#comments-dialog'))$('#comments-dialog').close()};$('#comments-dialog').addEventListener('close',()=>{commentGame=null;commentsRequest++});
$('#comment-form').onsubmit=async e=>{e.preventDefault();const form=e.target,id=commentGame,data=new FormData(form),button=form.querySelector('button');button.disabled=true;commentStatus('Posting…');try{engagement[id]=await api('/api/comments',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({gameId:id,name:data.get('name'),body:data.get('body')})});form.elements.body.value='';updateSocial(cards.get(id));if(commentGame===id){await loadComments(id);commentStatus('Comment posted.')}}catch(error){commentStatus(error.message)}finally{button.disabled=false}};
$('#submission').onsubmit=async e=>{e.preventDefault();const form=e.target,status=$('#form-status'),button=form.querySelector('button[type="submit"]'),file=form.elements.file.files[0];if(!file){status.textContent='Select a demo or video to upload.';return}const ext=file.name.split('.').pop().toLowerCase();if(!['html','mp4','webm'].includes(ext)){status.textContent='Choose an HTML demo or MP4/WebM video.';return}if(file.size>(ext==='html'?5:30)*1024*1024){status.textContent=ext==='html'?'HTML demos must be under 5 MB.':'Videos must be under 30 MB.';return}button.disabled=true;button.textContent='Uploading…';status.textContent='Uploading your file. Keep this page open.';try{const result=await api('/api/uploads',{method:'POST',body:new FormData(form)});await refreshFeed();form.reset();status.textContent='Uploaded! Your game is now in the feed.';show('feed');document.querySelector('[data-filter="All"]').click();cards.get(result.id).el.scrollIntoView({block:'start'});toast('Your upload is in the feed')}catch(error){status.textContent=error.message}finally{button.disabled=false;button.textContent='Upload to feed'}};
refreshFeed().catch(error=>toast(error.message));
// Refresh shared counts when visitors return to this tab. No optimistic fake counts.
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshFeed().catch(()=>{})});
